import{_ as e,o as r,c as a,a5 as s}from"./chunks/framework.CnBNXlt7.js";const h=JSON.parse('{"title":"PS 技巧","description":"","frontmatter":{},"headers":[],"relativePath":"tools/others/ps.md","filePath":"tools/others/ps.md","lastUpdated":1770391959000}'),o={name:"tools/others/ps.md"};function p(n,t,i,l,_,d){return r(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="ps-技巧" tabindex="-1">PS 技巧 <a class="header-anchor" href="#ps-技巧" aria-label="Permalink to &quot;PS 技巧&quot;">​</a></h1><h2 id="ps如何等比例裁剪" tabindex="-1">ps如何等比例裁剪 <a class="header-anchor" href="#ps如何等比例裁剪" aria-label="Permalink to &quot;ps如何等比例裁剪&quot;">​</a></h2><p>方法一：快捷键快速等比例裁剪（临时比例）<br> 打开图片，按 C 激活裁剪工具，图像四周出现裁剪框。<br> 按住 Shift 键拖动裁剪框的对角控制点，裁剪区域会按原始比例等比缩放；同时按住 Shift+Alt，可从中心向四周等比缩放。<br> 调整好保留区域后，按 Enter 键或双击裁剪框内确认裁剪。</p><p>方法二：预设 / 自定义固定比例裁剪（精准比例）<br> 激活裁剪工具（C），在顶部选项栏找到 “比例” 下拉菜单。<br> 选择内置比例（如 1:1、4:3、16:9 等），或选择 “比例” 后手动输入自定义宽高比（如 3:2）。<br> 拖动裁剪框或控制点，框会强制保持设定比例，仅调整位置与大小。<br> 确认后按 Enter 或点击选项栏的 ✅ 完成裁剪。</p><p>方法三：固定尺寸 + 比例裁剪（精确尺寸）<br> 激活裁剪工具，在选项栏输入固定的宽、高、分辨率（如 800px 宽、600px 高、72dpi）。<br> 拖动裁剪框选取保留区域，系统会自动按设定比例与尺寸裁剪。<br> 按 Enter 或双击完成，裁剪后图像尺寸与分辨率即符合输入值。</p>',5)])])}const b=e(o,[["render",p]]);export{h as __pageData,b as default};
